mapper.blocks:
{          
      "blocks": [                                                                                                                 
          {
              "type": "header",                                                                                                                                                                           
              "text": {
                  "type": "plain_text",                                                                                                                                                                   
                  "text": "🔔 | New `{{1.submission.locationRoute}}` Lead",
                  "emoji": true                                                                                                                                                                           
              }
          },                                                                                                                                                                                              
          {                                                 
              "type": "section",
              "fields": [
                  {
                      "type": "mrkdwn",
                      "text": "*Name:*\n{{1.user.lastName}}, {{1.user.firstName}}"
                  },                                                                                                                                                                                      
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Email:*\n{{1.user.email}}"  
                  },
                  {
                      "type": "mrkdwn",
                      "text": "*Phone:*\n{{1.user.phone.international}}"                                                                                                                                  
                  },
                  {                                                                                                                                                                                       
                      "type": "mrkdwn",                     
                      "text": "*Location:*\n{{1.submission.data.postalCode}} {{1.submission.data.locality}}"
                  },                                                                                                                                                                                      
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Housing type:*\n`{{1.submission.data.housingStatus}}`"
                  },                                                                                                                                                                                      
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Timeline:*\n`{{1.submission.data.deadline}}`"
                  }
              ]
          },
          {
              "type": "section",
              "fields": [                                                                                                                                                                                 
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Language:*\n`{{1.session.locale}}`"
                  },
                  {
                      "type": "mrkdwn",
                      "text": "*Environment:*\n`{{1.submission.environment}}`"                                                                                                                            
                  }
              ]                                                                                                                                                                                           
          },                                                
          {
              "type": "divider"
          },
          {
              "type": "section",
              "text": {
                  "type": "mrkdwn",                                                                                                                                                                       
                  "text": "*📊 Attribution*"
              }                                                                                                                                                                                           
          },                                                
          {
              "type": "section",
              "fields": [                                                                                                                                                                                 
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Source / Medium:*\n`{{1.attribution.utm.utm_source}}` / `{{1.attribution.utm.utm_medium}}`"
                  },                                                                                                                                                                                      
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Campaign:*\n`{{1.attribution.utm.utm_campaign}}`"
                  },                                                                                                                                                                                      
                  {
                      "type": "mrkdwn",                                                                                                                                                                   
                      "text": "*Landing page:*\n{{1.attribution.landingPage}}"
                  },
                  {                                                                                                                                                                                       
                      "type": "mrkdwn",
                      "text": "*Click IDs:*\n{{ifempty(1.attribution.gclid; "–")}}"
                  }                                                                                                                                                                                       
              ]                                             
          },
          {
              "type": "divider"
          },                                                                                                                                                                                              
          {
              "type": "section",                                                                                                                                                                          
              "text": {                                     
                  "type": "mrkdwn",
                  "text": "*Dispatch status:* {{switch(46.isDispatchable; true; "✅"; false; "❌"; "⁇")}}"
              }                                                                                                                                                                                           
          },
          {                                                                                                                                                                                               
              "type": "section",                            
              "fields": [
                  {
                      "type": "mrkdwn",
                      "text": "*Partner:*\n{{68.partner_display_name}}"                                                                                                                                  
                  },
                  {                                                                                                                                                                                       
                      "type": "mrkdwn",                     
                      "text": "*Region:*\n{{1.submission.data.canton}}"
                  }                                                                                                                                                                                       
              ]
          },                                                                                                                                                                                              
          {                                                 
              "type": "divider"
          },
          {
              "type": "actions",
              "elements": [
                  {
                      "type": "button",
                      "text": {
                          "type": "plain_text",
                          "text": "📋 View in Directus",                                                                                                                                                  
                          "emoji": true
                      },                                                                                                                                                                                  
                      "url": "https://cms.easyrecharge.ch/admin/content/form_submissions/{{1.submission.id}}",
                      "style": "primary"                                                                                                                                                                  
                  },
                  {                                                                                                                                                                                       
                      "type": "button",                     
                      "text": {
                          "type": "plain_text",
                          "text": "👤 Contact record",
                          "emoji": true
                      },                                                                                                                                                                                  
                      "url": "https://cms.easyrecharge.ch/admin/content/form_users/{{1.user.id}}"
                  },                                                                                                                                                                                      
                  {                                         
                      "type": "button",
                      "text": {
                          "type": "plain_text",                                                                                                                                                           
                          "text": "📈 PostHog",
                          "emoji": true                                                                                                                                                                   
                      },                                    
                      "url": "{{1.posthog.personUrl}}"
                  }                                                                                                                                                                                       
              ]
          },                                                                                                                                                                                              
          {                                                 
              "type": "context",
              "elements": [
                  {
                      "type": "mrkdwn",
                      "text": "Submitted at {{1.submission.submittedAt}} • <https://cms.easyrecharge.ch/admin/content/form_sessions/{{1.session.id}}|Session {{1.session.id}}>"
                  }                                                                                                                                                                                       
              ]
          }                                                                                                                                                                                               
      ]                                                     
  }
